-- CHAMBA 052 — Al completar chamba: acreditar billetera (payment_status) y métricas técnicoCREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS worker_advance_operational_phase CASCADE;CREATE OR REPLACE FUNCTION worker_advance_operational_phase(  p_job_id UUID,  p_worker_id UUID,  p_phase TEXT)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_status job_status;  v_now TIMESTAMPTZ := NOW();  v_rows INT;BEGIN  IF p_phase NOT IN ('accepted', 'en_route', 'arrived', 'completed') THEN    RETURN jsonb_build_object('success', false, 'error', 'Fase inválida');  END IF;  IF NOT EXISTS (    SELECT 1 FROM job_assignments     WHERE job_id = p_job_id AND worker_id = p_worker_id  ) AND NOT EXISTS (    SELECT 1 FROM jobs     WHERE id = p_job_id AND assigned_worker_id = p_worker_id  ) THEN    RETURN jsonb_build_object('success', false, 'error', 'Sin asignación');  END IF;  v_status := CASE p_phase    WHEN 'completed' THEN 'completed'::job_status    WHEN 'arrived' THEN 'in_progress'::job_status    ELSE 'taken'::job_status  END;  UPDATE jobs     SET operational_phase = p_phase,         status = v_status,         updated_at = v_now   WHERE id = p_job_id;  IF p_phase = 'completed' THEN    UPDATE job_assignments       SET completed_at = v_now,           payment_status = CASE             WHEN payment_status::text IN ('paid', 'processing') THEN payment_status             ELSE 'pending'::payment_status           END     WHERE job_id = p_job_id       AND worker_id = p_worker_id       AND selection_status = 'approved'       AND completed_at IS NULL;    GET DIAGNOSTICS v_rows = ROW_COUNT;    IF v_rows > 0 THEN      INSERT INTO worker_profiles (worker_id, skills, availability_status, total_jobs_done)      VALUES (p_worker_id, '{}', 'available', 1)      ON CONFLICT (worker_id) DO UPDATE        SET total_jobs_done = COALESCE(worker_profiles.total_jobs_done, 0) + 1;    END IF;  END IF;  RETURN jsonb_build_object('success', true, 'phase', p_phase, 'status', v_status::text);END;$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS worker_complete_job CASCADE;CREATE OR REPLACE FUNCTION worker_complete_job(  p_job_id UUID,  p_worker_id UUID,  p_assignment_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_now TIMESTAMPTZ := NOW();  v_rows INT;BEGIN  IF NOT EXISTS (    SELECT 1 FROM job_assignments     WHERE id = p_assignment_id       AND job_id = p_job_id       AND worker_id = p_worker_id       AND selection_status = 'approved'  ) THEN    RETURN jsonb_build_object('success', false, 'error', 'Asignación inválida');  END IF;  UPDATE jobs     SET status = 'completed'::job_status,         operational_phase = 'completed',         updated_at = v_now   WHERE id = p_job_id;  UPDATE job_assignments     SET completed_at = v_now,         payment_status = CASE           WHEN payment_status::text IN ('paid', 'processing') THEN payment_status           ELSE 'pending'::payment_status         END   WHERE id = p_assignment_id     AND completed_at IS NULL;  GET DIAGNOSTICS v_rows = ROW_COUNT;  IF v_rows > 0 THEN    INSERT INTO worker_profiles (worker_id, skills, availability_status, total_jobs_done)    VALUES (p_worker_id, '{}', 'available', 1)    ON CONFLICT (worker_id) DO UPDATE      SET total_jobs_done = COALESCE(worker_profiles.total_jobs_done, 0) + 1;  END IF;  RETURN jsonb_build_object('success', true);END;$$;GRANT EXECUTE ON FUNCTION worker_advance_operational_phase(UUID, UUID, TEXT)  TO anon, authenticated;GRANT EXECUTE ON FUNCTION worker_complete_job(UUID, UUID, UUID)  TO anon, authenticated;NOTIFY pgrst, 'reload schema';